/**
 * Hands generated bytes to the browser as a download. Used by the battle report, which is built
 * on the device and never persisted anywhere - not in localStorage, not on the server.
 */
export function downloadPdf(filename: string, bytes: Uint8Array): void {
	const blob = new Blob([bytes.buffer as ArrayBuffer], { type: 'application/pdf' });
	const url = URL.createObjectURL(blob);
	const anchor = document.createElement('a');
	anchor.href = url;
	anchor.download = filename;
	document.body.appendChild(anchor);
	anchor.click();
	anchor.remove();
	URL.revokeObjectURL(url);
}
